package main
import("context";"encoding/json";"errors";"os";"time";"github.com/jackc/pgx/v5/pgtype";"workpal.local/workpal/server/internal/events";"workpal.local/workpal/server/internal/util";db "workpal.local/workpal/server/pkg/db/generated")
type step struct{Event events.Event;Time float64;Rows [][]*string;Projects []string;Fail bool}
type queries struct{audienceQuerier;state step;calls []string}
func uuid(s string)pgtype.UUID{v,e:=util.ParseUUID(s);if e!=nil{panic(e)};return v}
func(q *queries)ListPrivateProjectAudience(context.Context,pgtype.UUID)([]db.ListPrivateProjectAudienceRow,error){q.calls=append(q.calls,"workspace");if q.state.Fail{return nil,errors.New("database down")};rows:=[]db.ListPrivateProjectAudienceRow{};for _,r:=range q.state.Rows{row:=db.ListPrivateProjectAudienceRow{ProjectID:uuid(*r[0])};if r[1]!=nil{row.UserID=uuid(*r[1])};rows=append(rows,row)};return rows,nil}
func(q *queries)GetAgentTask(context.Context,pgtype.UUID)(db.AgentTaskQueue,error){q.calls=append(q.calls,"task");payload:=map[string]any{"type":"quick_create"};if len(q.state.Projects)>0{payload["project_id"]=q.state.Projects[0]};if len(q.state.Projects)>1{payload["parent_issue_id"]="00000000-0000-0000-0000-000000000005"};raw,_:=json.Marshal(payload);return db.AgentTaskQueue{Context:raw},nil}
func(q *queries)ListIssueProjectIDs(context.Context,[]pgtype.UUID)([]db.ListIssueProjectIDsRow,error){q.calls=append(q.calls,"projects");return []db.ListIssueProjectIDsRow{{ID:uuid("00000000-0000-0000-0000-000000000005"),ProjectID:uuid(q.state.Projects[1])}},nil}
func main(){var scripts [][]step;if err:=json.NewDecoder(os.Stdin).Decode(&scripts);err!=nil{panic(err)};out:=[]any{};for _,steps:=range scripts{q:=&queries{calls:[]string{}};a:=newPrivateProjectAudience(q);results:=[]any{};for _,s:=range steps{q.state=s;a.now=func()time.Time{return time.Unix(0,int64(s.Time*1e9))};members,private,err:=a.Audience(context.Background(),s.Event);message:="";if err!=nil{message=err.Error()};results=append(results,map[string]any{"members":members,"private":private,"error":message,"calls":append([]string{},q.calls...)})};out=append(out,results)};json.NewEncoder(os.Stdout).Encode(out)}
